import 'package:go_router/go_router.dart';import 'package:flutter/material.dart';import '../../services/demo_store.dart';import '../../widgets/party_card.dart';class SearchScreen extends StatefulWidget{const SearchScreen({super.key});@override State<SearchScreen>createState()=>_SearchScreenState();}class _SearchScreenState extends State<SearchScreen>{String q='';@override Widget build(BuildContext c){final s=DemoStore.instance..init();final ps=s.parties.where((p)=>q.isEmpty||p.title.toLowerCase().contains(q.toLowerCase())||(p.description??'').toLowerCase().contains(q.toLowerCase())||(p.category??'').toLowerCase().contains(q.toLowerCase())).toList();return Scaffold(appBar:AppBar(title:TextField(autofocus:true,decoration:const InputDecoration(hintText:'Search'),onChanged:(v)=>setState(()=>q=v))),body:ListView.builder(padding:const EdgeInsets.all(16),itemCount:ps.length,itemBuilder:(_,i)=>Padding(padding:const EdgeInsets.only(bottom:12),child:PartyCard(party:ps[i],onTap:()=>GoRouter.of(c).push('/party/${ps[i].id}')))));}}
